import React, { useEffect, useState } from "react";
import Card from "./Card";
import api from "../services/api"; // Import the API service

const MonitoringWidget = () => {
  const [metrics, setMetrics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    // Make API request to fetch monitoring data
    api
      .get("http://203.143.13.21:8000/api/agent/metrics/") // Replace with the correct endpoint from your backend
      .then((response) => {
        setMetrics(response.data);
        setLoading(false);
      })
      .catch((err) => {
        setError("Failed to fetch metrics");
        setLoading(false);
      });
  }, []);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6">
      {metrics.map((metric, index) => (
        <Card key={index} title={metric.title} value={metric.value} />
      ))}
    </div>
  );
};

export default MonitoringWidget;
